import{_ as a,o as t,c as s,ag as n}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"从 has_sync 到端到端证据：相机与 IMU 时间同步 QA","description":"把时间同步验证做成可在线运行、可离线复盘、可进入 CI 的工程能力","frontmatter":{"title":"从 has_sync 到端到端证据：相机与 IMU 时间同步 QA","description":"把时间同步验证做成可在线运行、可离线复盘、可进入 CI 的工程能力","tags":["TimeSync","ROS","PX4","QA"],"date":"2026/06/29"},"headers":[],"relativePath":"uav/timesync-qa-engineering.md","filePath":"uav/timesync-qa-engineering.md","lastUpdated":1784519165000}'),i={name:"uav/timesync-qa-engineering.md"};function l(p,e,d,r,o,c){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="从-has-sync-到端到端证据-相机与-imu-时间同步-qa" tabindex="-1">从 <code>has_sync</code> 到端到端证据：相机与 IMU 时间同步 QA <a class="header-anchor" href="#从-has-sync-到端到端证据-相机与-imu-时间同步-qa" aria-label="Permalink to &quot;从 \`has_sync\` 到端到端证据：相机与 IMU 时间同步 QA&quot;">​</a></h1><p><code>has_sync=True</code> 很重要，但它只说明某一段同步链路建立了。它不能自动证明相机与 IMU 的消息时间戳已经落在同一时间轴，也不能证明多相机帧属于同一次触发。</p><p>要把时间同步从“看起来正常”变成可发布的工程能力，需要分层验证。</p><h2 id="五层同步问题" tabindex="-1">五层同步问题 <a class="header-anchor" href="#五层同步问题" aria-label="Permalink to &quot;五层同步问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>要回答的问题</th><th>典型证据</th></tr></thead><tbody><tr><td>链路</td><td>PPS / 串口消息是否持续到达</td><td>link state、消息率、丢包</td></tr><tr><td>时钟</td><td>offset 是否收敛且稳定</td><td>raw/smoothed offset、jitter</td></tr><tr><td>触发</td><td>多相机是否属于同一触发</td><td>trigger seq、bundle complete</td></tr><tr><td>时间域</td><td>相机与 IMU stamp 是否同域</td><td>stamp domain、转换路径</td></tr><tr><td>运动一致性</td><td>两类传感器是否在物理上对齐</td><td>光流/角速度相关性、激励条件</td></tr></tbody></table><p>任何一层通过，都不能替代下一层。</p><h2 id="_1-在线与离线必须复用同一个分析器" tabindex="-1">1. 在线与离线必须复用同一个分析器 <a class="header-anchor" href="#_1-在线与离线必须复用同一个分析器" aria-label="Permalink to &quot;1. 在线与离线必须复用同一个分析器&quot;">​</a></h2><p>最容易出现的维护问题是：在线节点用一套阈值，离线脚本又实现一套，最后同一份数据得到两个结论。</p><p>更好的结构是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rosbag / JSONL ─┐</span></span>
<span class="line"><span>                ├─&gt; shared analyzers ─&gt; summary model</span></span>
<span class="line"><span>ROS subscribers ┘                         ├─ summary.json</span></span>
<span class="line"><span>                                          ├─ report.html</span></span>
<span class="line"><span>                                          └─ junit.xml</span></span></code></pre></div><p>在线节点只负责收集滑动窗口，离线 CLI 只负责读取数据，两者把同一种事件模型交给共享 analyzer。</p><h2 id="_2-不要混用-receipt-time-与-header-stamp" tabindex="-1">2. 不要混用 receipt time 与 header stamp <a class="header-anchor" href="#_2-不要混用-receipt-time-与-header-stamp" aria-label="Permalink to &quot;2. 不要混用 receipt time 与 header stamp&quot;">​</a></h2><p>ROS 消息至少存在两类常见时间：</p><ul><li><code>header.stamp</code>：消息声明的事件时间；</li><li>receipt time：本机收到回调的时间。</li></ul><p>receipt time 会包含调度、传输和队列延迟。它可以衡量链路覆盖与消息新鲜度，但不能直接当作传感器物理 offset。</p><p>相机还可能有 driver PTS、group PTS、trigger time；IMU 可能有 PX4 sample time、同步后的 realtime 或 ROS publish time。QA 配置必须明确每个指标使用哪一个源。</p><h2 id="_3-多相机同步看-bundle-不只看平均频率" tabindex="-1">3. 多相机同步看 bundle，不只看平均频率 <a class="header-anchor" href="#_3-多相机同步看-bundle-不只看平均频率" aria-label="Permalink to &quot;3. 多相机同步看 bundle，不只看平均频率&quot;">​</a></h2><p>六路相机都在 20 Hz，不等于每个 bundle 都完整。需要按 <code>sync_seq</code> 或 <code>trigger_seq</code> 聚合，统计：</p><ul><li>bundle complete ratio；</li><li>同组最大 skew；</li><li>sequence gap；</li><li>重复帧与迟到帧；</li><li>滑动窗口边缘的半截 bundle。</li></ul><p>窗口起止位置天然会截断部分 bundle，因此边缘桶应显式忽略或单独标记，不能把它们误算成真实丢帧。</p><h2 id="_4-运动相关性需要足够激励" tabindex="-1">4. 运动相关性需要足够激励 <a class="header-anchor" href="#_4-运动相关性需要足够激励" aria-label="Permalink to &quot;4. 运动相关性需要足够激励&quot;">​</a></h2><p>用图像光流与 gyro 估计 camera-IMU offset 时，如果设备静止，视觉变化和角速度都接近噪声底，算法即使输出一个数也不可信。</p><p>测试应包含明确的旋转或运动激励，并设置最低能量门限：激励不足就输出 <code>INSUFFICIENT_EXCITATION</code>，而不是给出伪精确 offset。</p><h2 id="_5-qa-输出要能进入发布门禁" tabindex="-1">5. QA 输出要能进入发布门禁 <a class="header-anchor" href="#_5-qa-输出要能进入发布门禁" aria-label="Permalink to &quot;5. QA 输出要能进入发布门禁&quot;">​</a></h2><p>建议同时输出三种形式：</p><ul><li><code>summary.json</code>：给自动化系统和后续聚合；</li><li><code>report.html</code>：给工程师快速阅读；</li><li><code>junit.xml</code>：直接进入 CI 测试结果。</li></ul><p>一个典型 gate 可以包含：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>link_up == true</span></span>
<span class="line"><span>offset_jitter_p99 &lt; threshold</span></span>
<span class="line"><span>bundle_complete_ratio &gt;= threshold</span></span>
<span class="line"><span>camera_skew_p99 &lt; threshold</span></span>
<span class="line"><span>imu_rate within expected range</span></span>
<span class="line"><span>time_domain_consistent == true</span></span></code></pre></div><p>阈值应来自硬件和算法需求，而不是为了让当前数据通过。</p><h2 id="最终验收边界" tabindex="-1">最终验收边界 <a class="header-anchor" href="#最终验收边界" aria-label="Permalink to &quot;最终验收边界&quot;">​</a></h2><p>时间同步 QA 至少要区分：</p><ul><li>代码单测通过；</li><li>离线样例通过；</li><li>板端在线窗口通过；</li><li>动态激励下物理 offset 可估；</li><li>正式 release/service 已部署。</li></ul><p>把这些层次分开，才能避免用“节点 active”或“has_sync 为真”替代真正的端到端同步证据。</p>`,33)])])}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
